import{_ as n,a as l,b as r}from"./chunks/out-of-space.D_ukUxGE.js";import{_ as i,C as d,o as h,c as u,a2 as o,j as e,a as t,E as c}from"./chunks/framework.C0pL2NcE.js";const b="/colony-flow-sand/docs/assets/sand-board.BUt3SG_m.png",p="/colony-flow-sand/docs/assets/frozen.DByO4f_E.png",m="/colony-flow-sand/docs/assets/conveyor.Bz2VyGqe.png",f="/colony-flow-sand/docs/assets/nests.DwkF3V-S.png",g="/colony-flow-sand/docs/assets/hud.DXtPn4mv.png",P=JSON.parse('{"title":"1. Core gameplay","description":"","frontmatter":{"pageClass":"gdd-wide"},"headers":[],"relativePath":"gdd/core-gameplay.md","filePath":"gdd/core-gameplay.md"}'),w={name:"gdd/core-gameplay.md"},y={class:"gdd-table"},v={id:"obstacle-frozen"};function k(_,a,x,T,A,S){const s=d("Badge");return h(),u("div",null,[a[5]||(a[5]=o('<h1 id="_1-core-gameplay" tabindex="-1">1. Core gameplay <a class="header-anchor" href="#_1-core-gameplay" aria-label="Permalink to &quot;1. Core gameplay&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Date</th><th>Detail</th><th>Author</th></tr></thead><tbody><tr><td>2026-10-27</td><td>Initial design (GDD created)</td><td>Tuan Dinh Duc</td></tr><tr><td>2026-11-03</td><td>Rewritten in the core gameplay format: an overview, then one table per screen zone</td><td>Tuan Dinh Duc</td></tr></tbody></table><p>Every change to the game, build by build, is in the <a href="./changelog">Changelog</a>. Sizes and positions are in world pixels on the 1080 × 1920 portrait game screen; every number comes from the current code (<code>src/game/layout.ts</code>, <code>src/game/sim.ts</code>).</p><h2 id="i-overview" tabindex="-1">I. Overview <a class="header-anchor" href="#i-overview" aria-label="Permalink to &quot;I. Overview&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th><th style="width:22%;">Demo</th></tr></thead><tbody><tr><td><img src="'+n+'" alt="The game screen"></td><td><p><b>How to play:</b></p><ul><li>A picture made of coloured sand fills a frame. The player swipes the sand to set it free.</li><li>Freed sand falls into the funnel under the frame and down a hole, where every 64 grains of one colour are pressed into a block.</li><li>The blocks come out of the gate under the frame onto a conveyor that runs round and round.</li><li>Ant nests wait under the conveyor, each for blocks of one colour. When a block of its colour passes, an ant walks out, takes it and carries it home, and the number on the nest counts down.</li><li>A full nest pops and the next nest in its column moves up.</li><li>The tension: the conveyor has 36 slots. Releasing a colour no front nest wants fills it up.</li></ul><p><b>Win:</b></p><ul><li>Every nest has all its blocks.</li></ul><p><b>Lose:</b></p><ul><li>All 30 conveyor slots hold a block and none of them can go into a nest any more (no front nest wants a colour on the belt, no ant is on its way and no nest is popping) for more than 0.35 s: <b>Out of Space!</b></li></ul><p><b>Session:</b> a level takes about 30 to 150 seconds. The last level reached is remembered.</p></td><td><p><b>Play:</b> <a href="https://tuandds.github.io/colony-flow-sand/demo/" target="_blank">demo</a></p><p><b>Gameplay reels</b> (the game plays itself): <a href="https://tuandds.github.io/colony-flow-sand/demo/?demo=drops30" target="_blank">drops30</a>, <a href="https://tuandds.github.io/colony-flow-sand/demo/?demo=mix60" target="_blank">mix60</a>; see <a href="../guide/demo-videos">Demo Videos</a></p><p><b>Level Editor:</b> <a href="https://tuandds.github.io/colony-flow-sand/demo/editor.html" target="_blank">editor</a></p></td></tr></tbody></table><p><strong>Screen layout</strong> (top to bottom):</p><table tabindex="0"><thead><tr><th>Zone</th><th>Share of the screen height</th><th>Position (y)</th></tr></thead><tbody><tr><td><a href="#_4-hud-boosters">4. HUD &amp; boosters</a></td><td>about 14 %</td><td>0 – 270</td></tr><tr><td><a href="#_1-sand-board-funnel">1. Sand board &amp; funnel</a></td><td>about 57 %</td><td>279 – 1378</td></tr><tr><td><a href="#_2-conveyor">2. Conveyor</a></td><td>about 12 %</td><td>1380 – 1604</td></tr><tr><td><a href="#_3-nests-ants">3. Nests &amp; ants</a></td><td>about 17 % (two rows and a half on screen)</td><td>1604 – 1920</td></tr></tbody></table><h2 id="_1-sand-board-funnel" tabindex="-1">1. Sand board &amp; funnel <a class="header-anchor" href="#_1-sand-board-funnel" aria-label="Permalink to &quot;1. Sand board &amp; funnel&quot;">​</a></h2>',8)),e("table",y,[a[4]||(a[4]=e("thead",null,[e("tr",null,[e("th",{style:{width:"30%"}},"Fakescreen"),e("th",null,"Details")])],-1)),e("tbody",null,[a[3]||(a[3]=e("tr",null,[e("td",null,[e("img",{src:b,alt:"The sand board and its funnel"})]),e("td",null,[e("p",null,[e("b",null,"Structure:"),t(" about 57 % of the screen height: the picture frame and its funnel, one piece of art ("),e("code",null,"img/frame.png"),t(").")]),e("ul",null,[e("li",null,[e("b",null,"Board:"),t(" the frame's inside, 824 × 776 px at (128, 330), under the frame's lilac top band. Its bottom corners are rounded like the art's, where they begin to curve into the funnel; no sand goes there. At the top the art is already full width, so sand fills the corners.")]),e("li",null,[e("b",null,"Picture:"),t(" up to 136 × 128 grains (16 cells tall; a cell is 8 × 8 grains, 48 px; a grain is about 6 px, drawn a little wider so the frame's grains span its inside exactly). The scale is the same in every level; a smaller picture sits centred. A full frame is exactly 272 blocks. A level may zoom its grains instead ("),e("b",null,"Phóng to hạt"),t(", from 1× to 2×): every grain is that many times as big, so the same grains make a bigger picture, in a frame that holds fewer (2×: 68 × 64 grains of about 12 px); sand falls at the same speed on screen and loose islands are the same size on screen at any zoom. ")]),e("li",null,[e("b",null,"Colours:"),t(" each level uses its own few colours (4 to 6 in the current levels, up to 12) from the 30 standard colours, the colours of Cube Blast's voxel materials (see "),e("a",{href:"../guide/level-editor#_1-colour-bank"},"Colour Bank"),t(").")]),e("li",null,[e("b",null,"Funnel:"),t(" as wide as the board at the top (824 px), its sides curve in, as the art's do, to the hole (about 75 px wide) 183 px under the board. The spout ends over the "),e("b",null,"gate"),t(" at the bottom of the frame, just above the conveyor.")])]),e("p",null,[e("b",null,"Sand:")]),e("ul",null,[e("li",null,[t("Sand is "),e("b",null,"fixed"),t(" until swiped. A swipe frees the sand within 38.5 px of the finger; freed sand is "),e("b",null,"loose"),t(" and drawn 22 % brighter.")]),e("li",null,"Loose sand falls with gravity 0.065 grains/step² up to 2.5 grains/step (the same speed on screen as with the earlier, smaller grains), at 110 steps per second. Blocked below, it slides down-left or down-right; on gentle slopes it creeps sideways toward a drop within 2 grains, with friction 0.82."),e("li",null,"Small or thin islands of fixed sand (40 grains or fewer, or narrower than 3 grains) come loose by themselves every 0.5 s."),e("li",null,[e("b",null,"The picture plays as drawn:"),t(" no grain is added, removed or recoloured when a level loads. Every 64 grains of a colour make a block, and a colour's leftover grains make its last block, so each colour makes its grains ÷ 64 blocks, rounded up.")])]),e("p",null,[e("b",null,"Funnel and hole:")]),e("ul",null,[e("li",null,[t("The board and the funnel are "),e("b",null,"one sand pile"),t(": the same grains fall from the board straight on into the funnel. Its curved sides are walls that loose sand slides down toward the hole.")]),e("li",null,[e("b",null,"First down, first out:"),t(" grains are numbered as they come into the funnel and move oldest first; the hole takes the oldest grains first. Sand comes out within about 3 blocks of the order it came down in.")]),e("li",null,"The hole takes 540 grains per second, but only while no finished block is waiting in it. Each colour is pressed on its own: a colour's sand waits under the hole until it has 64 grains (or its last grain is down)."),e("li",null,"When the hole is plugged or slower than the sand coming in, the funnel fills up and the sand piles back up into the board.")]),e("p",null,[e("b",null,"Position:"),t(" centred under the HUD; its gate sits just above the conveyor.")])])],-1)),e("tr",null,[a[2]||(a[2]=e("td",null,[e("img",{src:p,alt:"A Frozen area on level_6, counting 20"})],-1)),e("td",null,[e("h3",v,[a[0]||(a[0]=t("Obstacle: Frozen ",-1)),c(s,{type:"tip",text:"Live"})]),a[1]||(a[1]=o('<p>A patch of the picture locked under a sheet of ice, with a number on it.</p><ul><li><b>Shape:</b> a square/rectangle or a circle/ellipse, placed in picture grains (<code>frozen</code> in the level: <code>shape</code> <code>rect</code> or <code>circle</code>, <code>x</code>, <code>y</code>, <code>w</code>, <code>h</code>, <code>count</code>). A level may have several.</li><li><b>Locked:</b> the sand under the ice cannot be swept and never comes loose by itself (small islands next to it still do). Falling sand cannot enter it, so loose sand piles up on top of it.</li><li><b>Count:</b> the number goes down by 1 each time a nest is removed (a full nest pops and leaves its column). It pops a little each time it changes.</li><li><b>Break:</b> at 0 the ice shatters: its shards fly out and fall, the sheet fades out, and the sand it held becomes ordinary fixed sand that the player can sweep.</li><li><b>Look:</b> clear blue ice: the picture under it shows through, softened and tinted blue, so its pattern and colours can still be made out. It is cracked into pale cells, glows white along the inside of its edge and softly round its outside; a dark number with a white outline in the middle.</li><li><b>Level Editor:</b> the ❄️ tool (<code>F</code>) draws, moves and resizes areas on the picture; the Frozen section sets each one&#39;s shape, count and size, or deletes it (see the <a href="../guide/level-editor">Level Editor guide</a>). Areas show on the Sand Editor as a dashed outline with ❄ and the count.</li><li><b>In the levels:</b> none at the moment (the picture shows how it looked on level_6, where it was first tried).</li></ul>',2))])])])]),a[6]||(a[6]=o('<h2 id="_2-conveyor" tabindex="-1">2. Conveyor <a class="header-anchor" href="#_2-conveyor" aria-label="Permalink to &quot;2. Conveyor&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th></tr></thead><tbody><tr><td><img src="'+m+'" alt="The conveyor"></td><td><p><b>Structure:</b> about 12 % of the screen height.</p><ul><li>A loop track: straight runs from x 203 to 877, round ends of radius 50, centred at y 1492. The belt art (<code>img/conveyor.png</code>) is drawn with its own hollow in the wood round it.</li><li><b>36 slots</b> (about 46 px apart), each with a holder (a dark slate square); a block is a 32 px cube.</li><li>A fill gauge in the middle shows how full the belt is (a green bar and a percentage).</li></ul><p><b>Behaviour:</b></p><ul><li>The belt runs at 300 px/s.</li><li>A finished block waits in the gate&#39;s opening until an empty slot passes under it, then drops onto the belt.</li><li>Blocks ride round until an ant takes them. A full belt is not a loss while ants can still take blocks off it (see <a href="#i-overview">Lose</a>).</li></ul><p><b>Position:</b> between the sand board&#39;s gate and the nests.</p></td></tr></tbody></table><h2 id="_3-nests-ants" tabindex="-1">3. Nests &amp; ants <a class="header-anchor" href="#_3-nests-ants" aria-label="Permalink to &quot;3. Nests &amp; ants&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th></tr></thead><tbody><tr><td><img src="'+f+'" alt="The nests"></td><td><p><b>Structure:</b> about 17 % of the screen height: two rows of nests and the third down to its number; the rest wait below the screen.</p><ul><li><b>Columns:</b> 4 (a level from the Level Editor can have 2 to 6), 172 px apart. Rows are 130 px apart, with 28 px more under the front row.</li><li><b>Nest:</b> a box in its colour showing how many blocks it still needs (a white number with a black stroke). Front nests are full height in a white frame; waiting nests are lower and paler.</li><li><b>Nest sizes:</b> set by hand in the Level Editor, or built by the game from the picture: the blocks are listed in the order the sand naturally comes out, cut into nests of <code>chunk × 2</code> blocks and dealt to the column with the least sand still queued.</li></ul><p><b>Behaviour:</b></p><ul><li>Only the front nest of each column is active (and nests woken by the Activate booster).</li><li>An ant leaves an active nest every 0.12 s while it still needs blocks and a matching block is on the belt. Ants walk at 420 px/s, are 74 px long and carry 26 px cubes.</li><li>Each ant leaves from its own spot on the nest&#39;s top edge (up to ±38 px from the centre) and heads off its block: it aims at a point a random 25–100 % of the way to where it would meet the block, so some ants chase their block and others cut across. Both come from the level&#39;s seeded random numbers, so a recorded play replays the same.</li><li>A full nest pops; the column slides up. Nests never change column.</li><li>When a column&#39;s last nest pops, the columns left slide together (in about 0.3 s) and stay centred on the screen, still 172 px apart, so no gap is left where it was. Ants and the Fan then aim at the columns&#39; new places.</li></ul><p><b>Position:</b> under the conveyor, to the bottom of the screen.</p></td></tr></tbody></table><h2 id="_4-hud-boosters" tabindex="-1">4. HUD &amp; boosters <a class="header-anchor" href="#_4-hud-boosters" aria-label="Permalink to &quot;4. HUD &amp; boosters&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th></tr></thead><tbody><tr><td><img src="'+g+'" alt="The HUD and boosters"></td><td><p><b>Structure:</b> about 14 % of the screen height.</p><ul><li><b>Settings button</b> (top left): the pause panel: close (resume), music, sound and vibration switches (kept in the browser), Restart, Home, and a cheat to jump to any level. Vibration buzzes when a nest fills, on a win and on a loss.</li><li><b>Level title:</b> &quot;Level N&quot;.</li><li><b>Boosters:</b> a row of three 126 px buttons under the title, each with 1 use per level on a red badge (a green plus when none are left). They unlock one by one: Activate at level 3, Shuffle at level 6, Fan at level 9; before that the button is grey with a padlock and its level, and tapping it shows &quot;Unlocks at Level N&quot;.</li><li><b>x2:</b> double speed. Once all the picture&#39;s sand is swept (none of it is left fixed, though some may still be falling), x2 turns on by itself and the button hides until the next level.</li></ul><p><b>Boosters:</b></p><ul><li><b>Activate</b> (the claw): tap it, then a nest waiting in the second or third row; ants work for that nest too, from where it stands, until it is full. The game holds still while you pick.</li><li><b>Shuffle:</b> the game holds still and the nests pulse; after 0.5 s they trade places at random (each keeps its blocks), sliding to their new places in about 0.5 s. Nests with an ant on its way stay put.</li><li><b>Fan</b> (the ball cannon): the screen dims and the cannon drops into the middle, sucks the conveyor&#39;s blocks into its mouth one by one, then shoots them, 0.2 s apart, into nests of their colour that still have room, upper rows first. The game holds still until the last block lands.</li><li>A booster that would do nothing (nothing to wake, swap or blow) only bounces and keeps its use.</li></ul><p><b>Desktop testing keys:</b> N / P next and previous level, R restart.</p></td></tr></tbody></table><h2 id="_5-result-screens" tabindex="-1">5. Result screens <a class="header-anchor" href="#_5-result-screens" aria-label="Permalink to &quot;5. Result screens&quot;">​</a></h2><table class="gdd-table"><thead><tr><th style="width:30%;">Fakescreen</th><th>Details</th></tr></thead><tbody><tr><td><img src="'+l+'" alt="The win screen"><br><img src="'+r+'" alt="Out of Space"></td><td><p><b>Win:</b> a blue background, &quot;Level N&quot; over the &quot;AMAZING&quot; title, a pile of coins in a glow with turning rays, &quot;+40&quot; coins and confetti. <b>Claim x2</b> (ad badge, 80 coins) and <b>Continue</b> both go on to the next level (no coins or ads yet).</p><p><b>Out of Space!</b> (the conveyor is full): a broken heart and two revives, <b>Free</b> (ad) and <b>900</b> coins. Either one closes the board and the ball cannon clears the belt into the nests (it does not use up the Fan booster), then play goes on. The ✕ gives up.</p><p><b>Level failed:</b> after giving up, a board shows the lives (four hearts and a blank one), the time to the next heart and &quot;Level failed!&quot;; <b>Try Again</b> starts the level over (lives are only shown for now).</p></td></tr></tbody></table><h2 id="gameplay-variants" tabindex="-1">Gameplay variants <a class="header-anchor" href="#gameplay-variants" aria-label="Permalink to &quot;Gameplay variants&quot;">​</a></h2><p>The same levels can be played under other rules (<code>?variant=&lt;n&gt;</code>, picked beside the Level Editor&#39;s Play button; <code>src/game/variant.ts</code>).</p><table tabindex="0"><thead><tr><th></th><th>Variant 1 (the game)</th><th>Variant 2</th><th>Variant 3</th></tr></thead><tbody><tr><td>Grains a block</td><td>64</td><td>16 (a picture makes about 4 times as many blocks)</td><td>as 1</td></tr><tr><td>Nests</td><td>as the level sets them</td><td>4 times as big, as many of them (a nest of 8 is about 32)</td><td>as 1</td></tr><tr><td>Ants</td><td>carry blocks from the belt to their nest</td><td>none: a block on the belt&#39;s bottom run jumps into the front nest of its colour right under it, as many as the nest still wants</td><td>as 1</td></tr><tr><td>Conveyor</td><td>36 slots on holders</td><td>100 blocks lying loose as glossy 3D cubes, moved by physics (<code>src/game/belt-physics.ts</code>): the belt drags each block along by friction, crowding blocks push each other apart (and a glancing bump spins them), the belt&#39;s two rims hold them on it, a block sliding over the belt (when it lands, or is pushed) rolls over the way it slides and settles on a face, and round the belt&#39;s ends the blocks turn with it. The belt grips less than it takes to round its ends at speed, so there blocks slide out against the outer rim and pile up. Now and then the belt jolts a block across it, in or out (more often back toward the middle), and it tumbles over as it goes, bouncing back off the rims, so the blocks roll in and out across the belt instead of staying where they landed. Blocks land at the mouth across the belt&#39;s width, already riding at nearly its speed, a few at once, and up to 4 finished blocks may wait before the hole plugs (about 23 blocks a second). Cubes are 28 px. No holders; 20 small arrows ride round with the belt, pointing the way it turns</td><td>as 1</td></tr><tr><td>Lose</td><td>the belt is full and none of its blocks fits a front nest</td><td>the same, with 100</td><td>as 1</td></tr></tbody></table>',11))])}const C=i(w,[["render",k]]);export{P as __pageData,C as default};
